export const STATION_KEY='valmont.station.v1';
export const CATALOG={PC:{label:'PC · poste de commandement',group:'fire',crew:2},VPCE:{label:'VPCE · berce alimentation',group:'fire',crew:2},VSAV_MASTER:{label:'VSAV · Renault Master',group:'medical',crew:3},VSAV_MAN:{label:'VSAV · MAN TGE',group:'medical',crew:3},VSAV:{label:'VSAV · cellule',group:'medical',crew:3},VLI:{label:'VLI',group:'medical',crew:1},VSR:{label:'VSR · secours routier',group:'fire',crew:3},FPTSR:{label:'FPTSR · 3 000 L',group:'fire',crew:6},FPTL:{label:'FPTL · 2 000 L',group:'fire',crew:4},CCFL:{label:'CCFL · 2 000 L',group:'fire',crew:3},CCF:{label:'CCFM · 4 000 L',group:'fire',crew:4},CCF8000:{label:'CCFS · 8 000 L',group:'fire',crew:4},EPA:{label:'EPA',group:'fire',crew:2},VTU:{label:'VTU',group:'fire',crew:2},VPL:{label:'VPL + bateau',group:'fire',crew:3}};
export const ccfLabel=e=>e.lightForest?'CCFL':(e.tankCapacity||e.capacity||4000)>=8000?'CCFS':'CCFM';
export const modelKey=e=>e.kind==='CCF'&&e.lightForest?'CCFL':e.kind==='VSAV'&&e.ambulanceModel==='master'?'VSAV_MASTER':e.kind==='VSAV'&&e.ambulanceModel==='man'?'VSAV_MAN':e.kind==='FPT'?(e.lightPump?'FPTL':'FPTSR'):e.kind==='CCF'&&e.tankCapacity===8000?'CCF8000':e.kind;
export function defaultComposition(fleet){return fleet.filter(e=>e.kind!=='VLCG').map(e=>({type:modelKey(e),signal:e.kind==='CCF'?'round':'standard',foam:true,lighting:true}));}
export function signalChoices(type){if(['CCFL','CCF','CCF8000'].includes(type))return ['round'];return ['VSAV','VSAV_MAN','VSAV_MASTER'].includes(type)?['standard','short','wide','round']:['FPTSR','FPTL','VSR'].includes(type)?['standard','wide','round']:['CCF','CCF8000','EPA'].includes(type)?['standard','round']:['standard'];}
export function signalZoneChoices(type){return ['CCFL','CCF','CCF8000'].includes(type)?['round']:['standard','short','wide','round'];}
export function normalizeComposition(raw,fleet){const defaults=defaultComposition(fleet),slots=fleet.filter(e=>e.kind!=='VLCG');return defaults.map((fallback,i)=>{const row=Array.isArray(raw)?raw[i]:null;if(!row||typeof row!=='object')return fallback;const medical=slots[i].home[0]>-70,type=row.type===''?'':CATALOG[row.type]?.group===(medical?'medical':'fire')?row.type:fallback.type;const allowed=signalZoneChoices(type),signalFront=allowed.includes(row.signalFront)?row.signalFront:allowed.includes(row.signal)?row.signal:allowed[0],signalRear=allowed.includes(row.signalRear)?row.signalRear:allowed.includes(row.signal)?row.signal:allowed[0];return {type,signalFront,signalRear,signal:signalChoices(type).includes(row.signal)?row.signal:signalChoices(type)[0],foam:row.foam!==false,lighting:row.lighting!==false};});}
export function compositionErrors(rows){const types=rows.map(r=>r.type);const missing=['VSAV','FPTSR','EPA','VPL'].filter(t=>t==='VSAV'?!types.some(k=>['VSAV','VSAV_MAN','VSAV_MASTER'].includes(k)):!types.includes(t));if(!types.some(t=>['CCFL','CCF','CCF8000'].includes(t)))missing.push('CCF');return [...(missing.length?['Pour couvrir les missions du jeu, conserver : '+missing.join(', ')+'.']:[]),...(types.filter(t=>t==='VLI').length>1?['Un seul VLI : un infirmier est disponible.']:[])];}
export function loadComposition(fleet,storage=globalThis.localStorage){try{const raw=JSON.parse(storage?.getItem(STATION_KEY)||'null');if(!raw)return null;const rows=normalizeComposition(raw,fleet);return compositionErrors(rows).length?null:rows;}catch{return null;}}
export function saveComposition(rows,fleet,storage=globalThis.localStorage){const clean=normalizeComposition(rows,fleet),errors=compositionErrors(clean);if(errors.length)return {error:errors.join(' ')};try{if(!storage)throw Error();storage.setItem(STATION_KEY,JSON.stringify(clean));return {rows:clean};}catch{return {error:'Enregistrement impossible dans ce navigateur.'};}}
export function composedFleet(fleet,rows){if(!rows)return fleet;const templates=new Map(fleet.map(e=>[modelKey(e),e])),slots=fleet.filter(e=>e.kind!=='VLCG'),counts={};const result=[];for(const [i,row]of normalizeComposition(rows,fleet).entries()){if(!row.type)continue;const base=['PC','VPCE'].includes(row.type)?{...templates.get('FPTSR'),kind:row.type,tankCapacity:0,size:2,name:row.type==='PC'?'Poste de commandement':'Porteur · berce alimentation longue distance'}:row.type==='CCFL'?{...templates.get('CCF'),lightForest:true,longChassis:false,tankCapacity:2000,size:3,name:'CCFL · citerne 2 000 L'}:row.type==='VSAV_MASTER'?{...templates.get('VSAV'),ambulanceModel:'master',name:'VSAV Renault Master'}:row.type==='VSAV_MAN'?{...templates.get('VSAV'),ambulanceModel:'man',name:'VSAV MAN TGE'}:row.type==='VSR'?{...templates.get('FPTSR'),kind:'VSR',tankCapacity:0,size:3,name:'Véhicule de secours routier'}:templates.get(row.type);if(!base)continue;const prefix=['VSAV_MAN','VSAV_MASTER'].includes(row.type)?'VSAV':['CCFL','CCF','CCF8000'].includes(row.type)?ccfLabel(base):row.type,n=counts[prefix]=(counts[prefix]||0)+1;const id=['FPTSR','VSR','EPA','VTU'].includes(prefix)&&n===1?prefix:prefix+' '+n;result.push({...base,id,home:[...slots[i].home],signalStyle:row.signal,signalFront:row.signalFront,signalRear:row.signalRear,foamEnabled:row.foam,lightingEnabled:row.lighting});}return [...result,...fleet.filter(e=>e.kind==='VLCG')];}
